    private static BigDecimal incomplete(LocalDate snapshotDate,LocalDate reportDate,BigDecimal rotation){need(snapshotDate.equals(reportDate),"ROTATION_COMPLETION_HISTORICAL_FALSE_UNVERIFIED");return rotation;}
