        public Quote quote(String symbol,String market,String brokerId,BigDecimal limit){BigDecimal value=Z,shares=Z;for(JsonNode row:assets.path("liveAssets").path("stocks"))if(symbol.equals(row.path("stockCode").asText())&&market.equals(row.path("market").asText())){if(brokerId!=null){JsonNode old=null;for(JsonNode s:assets.path("snapshot").path("stocks"))if(s.path("id").asText().equals(row.path("holdingId").asText())){old=s;break;}need(old!=null,"FLOOR_HOLDING_UNVERIFIED");if(!brokerId.equals(old.path("brokerId").asText()))continue;}value=value.add(nn(row.path("liveValue")),MC);shares=shares.add(nn(row.path("shares")),MC);}need(shares.signum()>0,"SHARED_EQUITY_COMMITMENT_SOURCE_UNAVAILABLE");BigDecimal mark=value.divide(shares,MC),upper=limit;JsonNode body;if(market.equals("台股"))body=c.sources().path("market:台股:"+symbol);else{body=null;for(JsonNode row:c.sources().path("market").path("symbols"))if(symbol.equals(row.path("stockCode").asText())){body=row;break;}}if(body!=null){if(body.path("quote").hasNonNull("price"))upper=upper.max(pos(body.path("quote").path("price")));for(String nativeBook:List.of("book","oddLotBook"))if(body.path(nativeBook).path("levels").isArray()&&!body.path(nativeBook).path("levels").isEmpty())upper=upper.max(pos(body.path(nativeBook).path("levels").get(0).path("bidPrice")));}BigDecimal rate=market.equals("美股")?fx():BigDecimal.ONE;if(market.equals("美股"))upper=upper.max(mark.divide(pos(assets.path("liveAssets").path("exchangeRate")),MC));return new Quote(mark,upper.multiply(rate,MC).max(mark),market.equals("美股")?rate:null);}
